import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../common/prisma/prisma.service';

export interface PlanValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
  suggestions: string[];
}

export interface PlanStructure {
  title: string;
  description: string;
  subjects: string[];
  goals: string[];
  weeks?: any[];
  totalSessions?: number;
  duration?: number;
}

export interface SessionStructure {
  subject: string;
  topic: string;
  duration: number;
  difficulty: string;
  type: string;
  startTime: Date;
  objectives?: string[];
  resources?: string[];
  techniques?: string[];
}

@Injectable()
export class PlanValidationService {
  private readonly logger = new Logger(PlanValidationService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Plan yapısını doğrula
   */
  validatePlan(plan: PlanStructure): PlanValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];
    const suggestions: string[] = [];

    // Temel alanlar kontrolü
    if (!plan.title || plan.title.trim().length === 0) {
      errors.push('Plan başlığı boş olamaz');
    }

    if (!plan.description || plan.description.trim().length === 0) {
      warnings.push('Plan açıklaması boş');
    }

    if (!plan.subjects || plan.subjects.length === 0) {
      errors.push('En az bir ders seçilmelidir');
    }

    if (!plan.goals || plan.goals.length === 0) {
      warnings.push('Plan hedefleri belirtilmemiş');
    }

    // Ders adları kontrolü
    if (plan.subjects) {
      const validSubjects = ['Matematik', 'Fizik', 'Kimya', 'Biyoloji', 'Türkçe', 'Tarih', 'Coğrafya', 'İngilizce'];
      const invalidSubjects = plan.subjects.filter(subject => !validSubjects.includes(subject));
      if (invalidSubjects.length > 0) {
        warnings.push(`Geçersiz ders adları: ${invalidSubjects.join(', ')}`);
      }
    }

    // Hedef kontrolü
    if (plan.goals) {
      plan.goals.forEach(goal => {
        if (goal.length < 5) {
          warnings.push(`Hedef çok kısa: "${goal}"`);
        }
      });
    }

    // Süre kontrolü
    if (plan.duration && plan.duration > 30) {
      warnings.push('Plan süresi 30 günden fazla');
    }

    if (plan.duration && plan.duration < 1) {
      errors.push('Plan süresi en az 1 gün olmalıdır');
    }

    // Hafta yapısı kontrolü
    if (plan.weeks) {
      this.validateWeeksStructure(plan.weeks, errors, warnings, suggestions);
    }

    // Öneriler
    if (plan.subjects && plan.subjects.length > 5) {
      suggestions.push('Çok fazla ders seçilmiş, odaklanma zorlaşabilir');
    }

    if (plan.goals && plan.goals.length > 10) {
      suggestions.push('Çok fazla hedef belirlenmiş, öncelik sıralaması yapılabilir');
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings,
      suggestions,
    };
  }

  /**
   * Seans yapısını doğrula
   */
  validateSessions(sessions: SessionStructure[]): PlanValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];
    const suggestions: string[] = [];

    if (!sessions || sessions.length === 0) {
      errors.push('En az bir seans olmalıdır');
      return { isValid: false, errors, warnings, suggestions };
    }

    // Her seans için kontrol
    sessions.forEach((session, index) => {
      this.validateSession(session, index, errors, warnings, suggestions);
    });

    // Genel seans kontrolleri
    this.validateSessionDistribution(sessions, errors, warnings, suggestions);
    this.validateSessionTiming(sessions, errors, warnings, suggestions);

    return {
      isValid: errors.length === 0,
      errors,
      warnings,
      suggestions,
    };
  }

  /**
   * Tek seans doğrulama
   */
  private validateSession(
    session: SessionStructure, 
    index: number, 
    errors: string[], 
    warnings: string[], 
    suggestions: string[]
  ): void {
    const sessionPrefix = `Seans ${index + 1}`;

    // Temel alanlar
    if (!session.subject || session.subject.trim().length === 0) {
      errors.push(`${sessionPrefix}: Ders adı boş olamaz`);
    }

    if (!session.topic || session.topic.trim().length === 0) {
      errors.push(`${sessionPrefix}: Konu adı boş olamaz`);
    }

    if (!session.duration || session.duration <= 0) {
      errors.push(`${sessionPrefix}: Süre 0'dan büyük olmalıdır`);
    }

    if (session.duration > 180) {
      warnings.push(`${sessionPrefix}: Süre çok uzun (${session.duration} dakika)`);
    }

    if (session.duration < 15) {
      warnings.push(`${sessionPrefix}: Süre çok kısa (${session.duration} dakika)`);
    }

    // Zorluk seviyesi
    const validDifficulties = ['easy', 'medium', 'hard'];
    if (!validDifficulties.includes(session.difficulty)) {
      errors.push(`${sessionPrefix}: Geçersiz zorluk seviyesi: ${session.difficulty}`);
    }

    // Seans türü
    const validTypes = ['study', 'review', 'practice', 'exam', 'break'];
    if (!validTypes.includes(session.type)) {
      errors.push(`${sessionPrefix}: Geçersiz seans türü: ${session.type}`);
    }

    // Tarih kontrolü
    if (session.startTime && session.startTime < new Date()) {
      warnings.push(`${sessionPrefix}: Geçmiş tarihli seans`);
    }

    // Hedefler kontrolü
    if (session.objectives && session.objectives.length > 5) {
      suggestions.push(`${sessionPrefix}: Çok fazla hedef, odaklanma zorlaşabilir`);
    }
  }

  /**
   * Hafta yapısı doğrulama
   */
  private validateWeeksStructure(
    weeks: any[], 
    errors: string[], 
    warnings: string[], 
    suggestions: string[]
  ): void {
    if (weeks.length === 0) {
      errors.push('En az bir hafta olmalıdır');
      return;
    }

    weeks.forEach((week, index) => {
      const weekPrefix = `Hafta ${index + 1}`;

      if (!week.weekNumber || week.weekNumber !== index + 1) {
        errors.push(`${weekPrefix}: Hafta numarası hatalı`);
      }

      if (!week.sessions || week.sessions.length === 0) {
        warnings.push(`${weekPrefix}: Seans bulunamadı`);
      }

      if (week.sessions && week.sessions.length > 20) {
        warnings.push(`${weekPrefix}: Çok fazla seans (${week.sessions.length})`);
      }

      // Hafta içi seans dağılımı
      if (week.sessions) {
        const dailySessions: Record<string, number> = {};
        week.sessions.forEach((session: any) => {
          const day = new Date(session.startTime).toDateString();
          dailySessions[day] = (dailySessions[day] || 0) + 1;
        });

        Object.entries(dailySessions).forEach(([day, count]) => {
          if (count > 5) {
            warnings.push(`${weekPrefix}: ${day} gününde çok fazla seans (${count})`);
          }
        });
      }
    });
  }

  /**
   * Seans dağılımı doğrulama
   */
  private validateSessionDistribution(
    sessions: SessionStructure[], 
    errors: string[], 
    warnings: string[], 
    suggestions: string[]
  ): void {
    // Ders dağılımı
    const subjectCount: Record<string, number> = {};
    sessions.forEach(session => {
      subjectCount[session.subject] = (subjectCount[session.subject] || 0) + 1;
    });

    const totalSessions = sessions.length;
    Object.entries(subjectCount).forEach(([subject, count]) => {
      const percentage = (count / totalSessions) * 100;
      
      if (percentage > 80) {
        warnings.push(`${subject} dersine çok fazla odaklanılmış (%${percentage.toFixed(1)})`);
      }
      
      if (percentage < 5) {
        suggestions.push(`${subject} dersine daha fazla zaman ayrılabilir (%${percentage.toFixed(1)})`);
      }
    });

    // Zorluk dağılımı
    const difficultyCount: Record<string, number> = {};
    sessions.forEach(session => {
      difficultyCount[session.difficulty] = (difficultyCount[session.difficulty] || 0) + 1;
    });

    const easyPercentage = (difficultyCount.easy || 0) / totalSessions * 100;
    const hardPercentage = (difficultyCount.hard || 0) / totalSessions * 100;

    if (easyPercentage > 70) {
      suggestions.push('Plan çok kolay, zorluk seviyesi artırılabilir');
    }

    if (hardPercentage > 50) {
      warnings.push('Plan çok zor, zorluk seviyesi azaltılabilir');
    }
  }

  /**
   * Seans zamanlaması doğrulama
   */
  private validateSessionTiming(
    sessions: SessionStructure[], 
    errors: string[], 
    warnings: string[], 
    suggestions: string[]
  ): void {
    // Tarih sıralaması
    const sortedSessions = [...sessions].sort((a, b) => 
      new Date(a.startTime).getTime() - new Date(b.startTime).getTime()
    );

    for (let i = 1; i < sortedSessions.length; i++) {
      const prevSession = sortedSessions[i - 1];
      const currentSession = sortedSessions[i];
      
      const prevEnd = new Date(prevSession.startTime.getTime() + prevSession.duration * 60000);
      const currentStart = new Date(currentSession.startTime);

      if (currentStart < prevEnd) {
        errors.push(`Seans ${i + 1} önceki seansla çakışıyor`);
      }

      // Çok kısa aralık
      const timeDiff = currentStart.getTime() - prevEnd.getTime();
      if (timeDiff < 15 * 60000) { // 15 dakikadan az
        warnings.push(`Seans ${i + 1} önceki seansla çok kısa aralıkta`);
      }
    }

    // Günlük seans sayısı
    const dailySessions: Record<string, number> = {};
    sessions.forEach(session => {
      const day = new Date(session.startTime).toDateString();
      dailySessions[day] = (dailySessions[day] || 0) + 1;
    });

    Object.entries(dailySessions).forEach(([day, count]) => {
      if (count > 8) {
        warnings.push(`${day} gününde çok fazla seans (${count})`);
      }
    });
  }

  /**
   * Kullanıcı bağlamına göre plan doğrulama
   */
  async validatePlanForUser(plan: PlanStructure, userId: string): Promise<PlanValidationResult> {
    const baseValidation = this.validatePlan(plan);
    
    if (!baseValidation.isValid) {
      return baseValidation;
    }

    // Kullanıcı profilini al
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { studentProfile: true },
    });

    if (!user?.studentProfile) {
      baseValidation.warnings.push('Kullanıcı profili bulunamadı, genel doğrulama yapıldı');
      return baseValidation;
    }

    // Sınıf seviyesi kontrolü
    const grade = user.studentProfile.grade;
    if (grade < 9 || grade > 12) {
      baseValidation.warnings.push(`Sınıf seviyesi uygun değil: ${grade}`);
    }

    // Öğrenme stili kontrolü
    const learningStyle = user.studentProfile.learningStyle;
    if (learningStyle && !['visual', 'auditory', 'kinesthetic', 'reading'].includes(learningStyle)) {
      baseValidation.warnings.push(`Geçersiz öğrenme stili: ${learningStyle}`);
    }

    return baseValidation;
  }

  /**
   * Plan optimizasyon önerileri
   */
  generateOptimizationSuggestions(plan: PlanStructure, sessions: SessionStructure[]): string[] {
    const suggestions: string[] = [];

    // Süre optimizasyonu
    const totalDuration = sessions.reduce((sum, session) => sum + session.duration, 0);
    const planDuration = plan.duration || 7;
    const dailyAverage = totalDuration / (planDuration * 7);

    if (dailyAverage > 300) { // 5 saatten fazla
      suggestions.push('Günlük çalışma süresi çok fazla, azaltılabilir');
    }

    if (dailyAverage < 60) { // 1 saatten az
      suggestions.push('Günlük çalışma süresi az, artırılabilir');
    }

    // Ders dengesi
    const subjectCount: Record<string, number> = {};
    sessions.forEach(session => {
      subjectCount[session.subject] = (subjectCount[session.subject] || 0) + 1;
    });

    const subjects = Object.keys(subjectCount);
    if (subjects.length > 0) {
      const maxCount = Math.max(...Object.values(subjectCount));
      const minCount = Math.min(...Object.values(subjectCount));
      
      if (maxCount / minCount > 3) {
        suggestions.push('Dersler arasında dengesizlik var, daha eşit dağıtılabilir');
      }
    }

    // Zorluk dengesi
    const difficultyCount: Record<string, number> = {};
    sessions.forEach(session => {
      difficultyCount[session.difficulty] = (difficultyCount[session.difficulty] || 0) + 1;
    });

    const totalSessions = sessions.length;
    const easyPercentage = (difficultyCount.easy || 0) / totalSessions * 100;
    const mediumPercentage = (difficultyCount.medium || 0) / totalSessions * 100;
    const hardPercentage = (difficultyCount.hard || 0) / totalSessions * 100;

    if (easyPercentage > 60) {
      suggestions.push('Plan çok kolay, zorluk seviyesi artırılabilir');
    }

    if (hardPercentage > 40) {
      suggestions.push('Plan çok zor, zorluk seviyesi azaltılabilir');
    }

    if (mediumPercentage < 30) {
      suggestions.push('Orta seviye seanslar artırılabilir');
    }

    return suggestions;
  }
}
